struct BarModeGeometry {
    int family = 0;
    int lower = 0;
    int upper = 0;
    double blend = 0.0;
};

inline BarModeGeometry GetBarModeGeometry(EMarimbaModel model, double noteNumber) {
    const int family = std::clamp(static_cast<int>(model), 0, 2);
    double transition = std::clamp((noteNumber - 72.0) / 24.0, 0.0, 1.0);
    transition = transition * transition * (3.0 - 2.0 * transition);
    const double index = transition * (kBarModeDepthCount - 1);
    const int lower = std::min(static_cast<int>(index), kBarModeDepthCount - 1);
    return {family, lower, std::min(lower + 1, kBarModeDepthCount - 1), index - lower};
}

inline double BarModeRatio(const BarModeGeometry& geometry, int mode) {
    mode = std::clamp(mode, 0, 7);
    const double a = kBarModeTables[geometry.family][geometry.lower].ratio[mode];
    const double b = kBarModeTables[geometry.family][geometry.upper].ratio[mode];
    return a + geometry.blend * (b - a);
}

namespace bar_detail {
constexpr double kGridStep = .5 / (kBarModePointCount - 1);
struct Cubic {
    double a, b, c, d;
    double Value(double z) const { return ((a*z+b)*z+c)*z+d; }
    double Slope(double z) const { return ((3*a*z+2*b)*z+c) / kGridStep; }
    double Integral(double z) const { return (((a*z/4+b/3)*z+c/2)*z+d)*z*kGridStep; }
    double SquareIntegral(double z) const {
        return ((((((a*a/7*z+a*b/3)*z+(b*b+2*a*c)/5)*z+(a*d+b*c)/2)*z
                   +(c*c+2*b*d)/3)*z+c*d)*z+d*d)*z*kGridStep;
    }
};
inline Cubic Segment(const BarModeGeometry& g, int mode, int index) {
    const auto& lo = kBarModeTables[g.family][g.lower];
    const auto& hi = kBarModeTables[g.family][g.upper];
    const auto blend = [&](double a, double b) { return a + g.blend * (b-a); };
    const double y0 = blend(lo.value[mode][index], hi.value[mode][index]);
    const double y1 = blend(lo.value[mode][index+1], hi.value[mode][index+1]);
    const double v0 = kGridStep * blend(lo.slope[mode][index], hi.slope[mode][index]);
    const double v1 = kGridStep * blend(lo.slope[mode][index+1], hi.slope[mode][index+1]);
    return {2*(y0-y1)+v0+v1, 3*(y1-y0)-2*v0-v1, v0, y0};
}
inline double HalfValue(const BarModeGeometry& g, int mode, double x, bool slope) {
    const double grid = std::clamp(x, 0.0, .5) / kGridStep;
    const int index = std::min(static_cast<int>(grid), kBarModePointCount-2);
    const Cubic polynomial = Segment(g, mode, index);
    return slope ? polynomial.Slope(grid-index) : polynomial.Value(grid-index);
}
inline double Point(const BarModeGeometry& g, int mode, double x, bool slope = false) {
    x = std::clamp(x, 0.0, 1.0);
    if (x <= .5) return HalfValue(g, mode, x, slope);
    const double sign = (mode % 2 == 0 ? 1.0 : -1.0) * (slope ? -1.0 : 1.0);
    return sign * HalfValue(g, mode, 1-x, slope);
}
inline double HalfIntegral(const BarModeGeometry& g, int mode, double x) {
    const double grid = std::clamp(x, 0.0, .5) / kGridStep;
    const int index = std::min(static_cast<int>(grid), kBarModePointCount-2);
    const auto& lo = kBarModeTables[g.family][g.lower];
    const auto& hi = kBarModeTables[g.family][g.upper];
    const double prefix = lo.integral[mode][index] + g.blend *
        (hi.integral[mode][index] - lo.integral[mode][index]);
    return prefix + Segment(g, mode, index).Integral(grid-index);
}
inline double Integral(const BarModeGeometry& g, int mode, double x) {
    x = std::clamp(x, 0.0, 1.0);
    if (x <= .5) return HalfIntegral(g,mode,x);
    const double middle = HalfIntegral(g,mode,.5);
    return middle + (mode % 2 == 0 ? 1.0 : -1.0) * (middle-HalfIntegral(g,mode,1-x));
}
inline double HalfSquareIntegral(const BarModeGeometry& g, int mode, double lo, double hi) {
    double sum = 0.0;
    int index = std::min(static_cast<int>(lo/kGridStep), kBarModePointCount-2);
    while (lo < hi && index < kBarModePointCount-1) {
        const double start = index*kGridStep;
        const double end = std::min(hi, start+kGridStep);
        const Cubic polynomial = Segment(g,mode,index);
        sum += polynomial.SquareIntegral((end-start)/kGridStep)
             - polynomial.SquareIntegral((lo-start)/kGridStep);
        lo = end;
        ++index;
    }
    return sum;
}
} // namespace bar_detail

inline double BarContactWeight(const BarModeGeometry& geometry, int mode,
        double position, double width) {
    mode = std::clamp(mode, 0, 7);
    const double x = std::clamp(position, 0.0, 1.0);
    const double half = .5*std::clamp(width, 0.0, .25);
    const double lo = std::max(0.0,x-half), hi = std::min(1.0,x+half);
    if (hi-lo < 1.e-8) return bar_detail::Point(geometry,mode,x);
    if (mode % 2 && lo+hi == 1.0) return 0.0;
    return (bar_detail::Integral(geometry,mode,hi)-bar_detail::Integral(geometry,mode,lo))/(hi-lo);
}

inline double BarContactParticipation(const BarModeGeometry& geometry, int mode,
        double position, double width) {
    mode = std::clamp(mode, 0, 7);
    const double x = std::clamp(position, 0.0, 1.0);
    const double half = .5*std::clamp(width, 0.0, .25);
    const double lo = std::max(0.0,x-half), hi = std::min(1.0,x+half);
    if (hi-lo < 1.e-8) {
        const double value = bar_detail::Point(geometry,mode,x);
        return value*value;
    }
    double sum = 0.0;
    if (lo < .5) sum += bar_detail::HalfSquareIntegral(geometry,mode,lo,std::min(hi,.5));
    if (hi > .5) sum += bar_detail::HalfSquareIntegral(geometry,mode,1-hi,1-std::max(lo,.5));
    return std::max(sum/(hi-lo),0.0);
}

inline double BarModeFundamentalNode(const BarModeGeometry& geometry) {
    double lo=.15, hi=.30;
    // Fixed 40-step bisection only when diagnostic callers ask for the node.
    for (int i=0;i<40;++i) {
        const double mid=.5*(lo+hi);
        if (bar_detail::Point(geometry,0,mid)<0.0) lo=mid; else hi=mid;
    }
    return .5*(lo+hi);
}

inline double BarModeStrainWeight(const BarModeGeometry& geometry, int mode) {
    static constexpr double position[3] = {.24,.29,.20};
    static constexpr double width[3] = {.10,.13,.09};
    const double lo=position[geometry.family]-.5*width[geometry.family];
    const double hi=position[geometry.family]+.5*width[geometry.family];
    // Mean curvature equals the difference of endpoint slopes / width.
    // Normalize to the fundamental at this same mount, once per note. This
    // preserves polarity and avoids a local per-mode nodal denominator.
    const double fundamental = bar_detail::Point(geometry,0,hi,true)-bar_detail::Point(geometry,0,lo,true);
    const double value = bar_detail::Point(geometry,std::clamp(mode,0,7),hi,true)
                       - bar_detail::Point(geometry,std::clamp(mode,0,7),lo,true);
    return value/fundamental;
}

